function htmlEntityEncode(str){return [...str].map((ch) =>{switch (ch){case "&": return "&amp;";case "<": return "&lt;";case ">": return "&gt;";case '"': return "&quot;";case "'": return "&#39;";default:{const cp = ch.codePointAt(0);return cp > 127 ? `&#${cp};` : ch;}}}).join("");}function htmlEntityDecode(str){const doc = new DOMParser().parseFromString(str, "text/html");return doc.documentElement.textContent;} const HTML_ENTITY_RE = /&(#\d+|#x[0-9a-f]+|[a-z][a-z0-9]*);/i;function executeHtmlEntityAuto(){const raw = document.getElementById("entity-input").value;const out = document.getElementById("entity-result");if (!raw){GAMA.say("idle");out.textContent = "";return;}out.textContent = HTML_ENTITY_RE.test(raw) ? htmlEntityDecode(raw) : htmlEntityEncode(raw);GAMA.say("success");}const executeHtmlEntityAutoDebounced = GAMA.debounce(executeHtmlEntityAuto, 300);